/*
 * pm_pwm_stm32f1.c - board PWM wiring: buzzer (PB9 / TIM3), register snapshot
 * for `PWM dbg`, PB8 test helper, and the dispatch table that routes model
 * channel ids to the TIM2 (motor) and TIM4 (servo) backends.
 *
 * PB9 can be muxed to TIM4_CH4, but this driver does not use that channel:
 * TIM4 stays on the servo frame (time base chosen by pm_pwm_timing_compute)
 * and the buzzer is generated by TIM3 update interrupts that toggle PB9 as a
 * plain GPIO at 10 us resolution. One timer could not give the servo its 50 Hz
 * frame and the buzzer a few kHz at the same time; this split keeps the servo
 * pulse train undisturbed while the buzzer runs, and the interrupt rate is only
 * 2x the tone (2..10 kHz at 100..5000 Hz).
 */
#include "pm_servo.h"

#include "stm32f1xx.h"

#include "pm_pwm.h"
#include "pm_pwm_tim2_stm32f1.h"
#include "pm_pwm_tim4_stm32f1.h"
#include "pm_timer_stm32f1.h"

#define BUZ_TICK_HZ       100000u   /* 10 us phase resolution */

static uint16_t s_buz_high;
static uint16_t s_buz_low;
static uint32_t s_buz_hz;
static uint8_t  s_buz_duty;
static uint8_t  s_buz_on;
static uint8_t  s_buz_phase;       /* 1 = pin high for the current phase */

void pm_pwm_board_init(void)
{
    /* Must run before the first claim: pm_pwm_init() for the servo happens
     * right after this call, and motor_dev_init() later. */
    pm_f1_timer_probe_install();

    RCC->APB2ENR |= RCC_APB2ENR_IOPBEN;
    RCC->APB1ENR |= RCC_APB1ENR_TIM3EN;

    /* PB9: plain push-pull output 2 MHz, toggled by the TIM3 ISR. */
    GPIOB->CRH = (GPIOB->CRH & ~(0xFu << 4)) | (0x2u << 4);
    GPIOB->BRR = GPIO_BRR_BR9;

    /* TIM3: 10 us tick, stopped until the buzzer is switched on. */
    TIM3->CR1  = 0u;
    TIM3->PSC  = (72000000u / BUZ_TICK_HZ) - 1u;
    TIM3->ARR  = 999u;
    TIM3->CNT  = 0u;
    TIM3->DIER = TIM_DIER_UIE;
    TIM3->EGR  = TIM_EGR_UG;
    TIM3->SR   = 0u;

    NVIC_ClearPendingIRQ(TIM3_IRQn);
    NVIC_SetPriority(TIM3_IRQn, 3);
    NVIC_EnableIRQ(TIM3_IRQn);
}

int pm_pwm_buzzer_set(uint32_t hz, uint8_t duty_pct)
{
    uint32_t period;
    uint32_t high;

    if ((hz < PM_PWM_BUZ_MIN_HZ) || (hz > PM_PWM_BUZ_MAX_HZ) ||
        (duty_pct < 1u) || (duty_pct > 99u)) {
        return -1;
    }
    period = BUZ_TICK_HZ / hz;
    if (period < 4u) {
        period = 4u;
    }
    high = (period * duty_pct) / 100u;
    if (high == 0u) {
        high = 1u;
    }
    if (high >= period) {
        high = period - 1u;
    }

    s_buz_high = (uint16_t)high;
    s_buz_low  = (uint16_t)(period - high);
    s_buz_hz   = hz;
    s_buz_duty = duty_pct;

    TIM3->CR1  = 0u;
    TIM3->CNT  = 0u;
    TIM3->ARR  = (uint16_t)(s_buz_high - 1u);
    TIM3->SR   = 0u;
    s_buz_phase = 1u;
    s_buz_on    = 1u;
    GPIOB->BSRR = GPIO_BSRR_BS9;
    TIM3->CR1   = TIM_CR1_CEN;
    return 0;
}

void pm_pwm_buzzer_off(void)
{
    TIM3->CR1  = 0u;
    TIM3->SR   = 0u;
    s_buz_on   = 0u;
    s_buz_phase = 0u;
    GPIOB->BRR = GPIO_BRR_BR9;
}

uint32_t pm_pwm_buzzer_hz(void)
{
    uint32_t period = (uint32_t)s_buz_high + (uint32_t)s_buz_low;

    return (period == 0u) ? 0u : (BUZ_TICK_HZ / period);
}

uint8_t pm_pwm_buzzer_duty(void)
{
    return s_buz_duty;
}

int pm_pwm_buzzer_on(void)
{
    return (int)s_buz_on;
}

void TIM3_IRQHandler(void)
{
    if ((TIM3->SR & TIM_SR_UIF) == 0u) {
        return;
    }
    TIM3->SR = ~TIM_SR_UIF;

    if (s_buz_phase != 0u) {
        GPIOB->BRR  = GPIO_BRR_BR9;
        TIM3->ARR   = (uint16_t)(s_buz_low - 1u);
        s_buz_phase = 0u;
    } else {
        GPIOB->BSRR = GPIO_BSRR_BS9;
        TIM3->ARR   = (uint16_t)(s_buz_high - 1u);
        s_buz_phase = 1u;
    }
}

/* --------------------------------------------------------- channel dispatch */

static const pm_pwm_ops_t *ops_for(uint8_t hw_id)
{
    if (hw_id < PM_F1_PWM_TIM2_COUNT) {
        return &pm_f1_tim2_pwm_ops;
    }
    if (hw_id == PM_PWM_HW_SERVO) {
        return &pm_f1_tim4_pwm_ops;
    }
    return NULL;
}

static pm_err_t pwm_open(void *ctx, pm_pwm_t *p, const pm_pwm_cfg_t *cfg,
                         uint32_t *actual_hz)
{
    const pm_pwm_ops_t *ops = (p == NULL) ? NULL : ops_for(p->hw_id);

    return (ops == NULL) ? PM_ERR_RANGE : ops->open(ctx, p, cfg, actual_hz);
}

static void pwm_close(void *ctx, pm_pwm_t *p)
{
    const pm_pwm_ops_t *ops = (p == NULL) ? NULL : ops_for(p->hw_id);

    if (ops != NULL) {
        ops->close(ctx, p);
    }
}

static pm_err_t pwm_set_freq(void *ctx, pm_pwm_t *p, uint32_t freq_hz,
                             uint32_t *actual_hz)
{
    const pm_pwm_ops_t *ops = (p == NULL) ? NULL : ops_for(p->hw_id);

    return (ops == NULL) ? PM_ERR_RANGE
                         : ops->set_freq(ctx, p, freq_hz, actual_hz);
}

static pm_err_t pwm_set_duty(void *ctx, pm_pwm_t *p, uint16_t permille)
{
    const pm_pwm_ops_t *ops = (p == NULL) ? NULL : ops_for(p->hw_id);

    return (ops == NULL) ? PM_ERR_RANGE : ops->set_duty(ctx, p, permille);
}

static pm_err_t pwm_enable(void *ctx, pm_pwm_t *p, bool on)
{
    const pm_pwm_ops_t *ops = (p == NULL) ? NULL : ops_for(p->hw_id);

    return (ops == NULL) ? PM_ERR_RANGE : ops->enable(ctx, p, on);
}

const pm_pwm_ops_t pm_f1_pwm_ops = {
    .open     = pwm_open,
    .close    = pwm_close,
    .set_freq = pwm_set_freq,
    .set_duty = pwm_set_duty,
    .enable   = pwm_enable,
};

/* ------------------------------------------------------------- diagnostics */

void pm_pwm_dbg_read(pm_pwm_dbg_t *out)
{
    uint32_t div;

    out->rcc_apb1enr = RCC->APB1ENR;
    out->rcc_apb2enr = RCC->APB2ENR;
    out->tim4_cr1    = TIM4->CR1;
    out->tim4_psc    = TIM4->PSC;
    out->tim4_arr    = TIM4->ARR;
    out->tim4_ccmr2  = TIM4->CCMR2;
    out->tim4_ccer   = TIM4->CCER;
    out->tim4_ccr3   = TIM4->CCR3;
    out->gpiob_crh   = GPIOB->CRH;
    out->afio_mapr   = AFIO->MAPR;

    /* Frame frequency implied by PSC/ARR; 0.1 Hz units so 50.0 is 500. */
    div = ((TIM4->PSC + 1u) * (TIM4->ARR + 1u));
    out->frame_hz10 = (div == 0u) ? 0u : (72000000u * 10u) / div;
}

uint32_t pm_pwm_counter(void)
{
    return TIM4->CNT;
}

void pm_pwm_test_begin(void)
{
    TIM4->CCER &= ~TIM_CCER_CC3E;
    GPIOB->CRH = (GPIOB->CRH & ~(0xFu << 0)) | (0x2u << 0);
    GPIOB->BRR = (1u << 8);
}

void pm_pwm_test_level(int high)
{
    if (high != 0) {
        GPIOB->BSRR = (1u << 8);
    } else {
        GPIOB->BRR = (1u << 8);
    }
}

void pm_pwm_test_end(void)
{
    GPIOB->CRH = (GPIOB->CRH & ~(0xFu << 0)) | (0xBu << 0);
    TIM4->CCR3 = 1500u;
    TIM4->CCER |= TIM_CCER_CC3E;
}
